class BaseRepository(ABC):
    """Abstract base class for all repositories."""

    def __init__(self):
        self.db_path = os.environ.get("DATABASE", "todos.db")

    def get_db(self):
        """Get a database connection."""
        conn = sqlite3.connect(self.db_path)
        conn.row_factory = sqlite3.Row
        return conn
